	"        return function(ctx)\n            local M = {}\n\n            local qualities = {\n                \"Broken\",\n                \"Refined\",\n                \"Pristine\",\n                \"Divine\",\n                \"Artifact\",\n                \"Transcendent\",\n            }\n\n            local qualityRank = {\n                Broken = 1,\n                Refined = 2,\n                Pristine = 3,\n                Divine = 4,\n                Artifact = 5,\n                Transcendent = 6,\n            }\n\n            local optionMap = {}\n            local optionMeta = {}\n            local dropdown = nil\n            local busy = false\n            local attempts = 0\n            local lastStatusText = nil\n\n            local cachedResultLabel = nil\n            local cachedReforgeRoot = nil\n            local lastLabelScan = 0\n\n            local function save()\n                if type(ctx.Save) == \"function\" then\n                    pcall(ctx.Save)\n                end\n            end\n\n            local function notify(title, content, duration)\n                if ctx.Notifier and type(ctx.Notifier.new) == \"function\" then\n                    pcall(function()\n                        ctx.Notifier.new({\n                            Title = title,\n                            Content = content,\n                            Duration = duration or 4,\n                        })\n                    end)\n                end\n            end\n\n            local function canonicalQuality(value)\n                local s = string.lower(tostring(value or \"\"))\n\n                for _, quality in ipairs(qualities) do\n                    if string.find(s, string.lower(quality), 1, true) then\n                        return quality\n                    end\n                end\n\n                return nil\n            end\n\n            local function normalizePercent(value)\n                local n = tonumber(value)\n                if not n then\n                    return nil\n                end\n\n                if n >= -20.05 and n <= 18.05 then\n                    return n\n                end\n\n                return nil\n            end\n\n            local function parsePercent(value)\n                local s = tostring(value or \"\")\n                local numberText = string.match(\n                    s,\n                    \"([%+%-]?%d+%.?%d*)%s*%%\"\n                )\n\n                if numberText then\n                    return normalizePercent(tonumber(numberText))\n                end\n\n                return nil\n            end\n\n            local function inferQuality(percent)\n                local p = normalizePercent(percent)\n                if p == nil then\n                    return nil\n                end\n\n                if p >= 15 then\n                    return \"Transcendent\"\n                elseif p >= 10 then\n                    return \"Artifact\"\n                elseif p >= 5 then\n                    return \"Divine\"\n                elseif p >= 0 then\n                    return \"Pristine\"\n                elseif p >= -10 then\n                    return \"Refined\"\n                elseif p >= -20 then\n                    return \"Broken\"\n                end\n\n                return nil\n            end\n\n            local function getInventory()\n                return ctx.LocalPlayer\n                    and ctx.LocalPlayer:FindFirstChild(\"Inventory\")\n                    or nil\n            end\n\n            local function readItemState(item, allowUI)\n                if not item or not item.Parent then\n                    return nil, nil\n                end\n\n                local quality = nil\n                local percent = nil\n                local attrs = item:GetAttributes()\n\n                local qualityKeys = {\n                    \"ReforgeQuality\",\n                    \"QualityName\",\n                    \"Quality\",\n                    \"ReforgeGrade\",\n                    \"QualityGrade\",\n                }\n\n                local percentKeys = {\n                    \"ReforgePercent\",\n                    \"ReforgePercentage\",\n                    \"QualityPercent\",\n                    \"QualityPercentage\",\n                    \"ReforgeBonusPercent\",\n                    \"QualityBonusPercent\",\n                }\n\n                for _, key in ipairs(qualityKeys) do\n                    local value = attrs[key]\n                    if value ~= nil then\n                        quality = canonicalQuality(value)\n                        if quality then\n                            break\n                        end\n                    end\n                end\n\n                for _, key in ipairs(percentKeys) do\n                    local value = attrs[key]\n                    if value ~= nil then\n                        percent = normalizePercent(value)\n                            or parsePercent(value)\n\n                        if percent ~= nil then\n                            break\n                        end\n                    end\n                end\n\n                if not quality or percent == nil then\n                    for key, value in pairs(attrs) do\n                        local keyLower = string.lower(tostring(key))\n                        local relevant =\n                            string.find(keyLower, \"reforge\", 1, true)\n                            or string.find(keyLower, \"quality\", 1, true)\n\n                        if relevant then\n                            if not quality then\n                                quality = canonicalQuality(value)\n                            end\n\n                            if percent == nil then\n                                percent = normalizePercent(value)\n                                    or parsePercent(value)\n                            end\n                        end\n                    end\n                end\n\n                if not quality or percent == nil then\n                    local inspected = 0\n\n                    for _, child in ipairs(item:GetDescendants()) do\n                        if child:IsA(\"ValueBase\") then\n                            inspected = inspected + 1\n                            if inspected > 80 then\n                                break\n                            end\n\n                            local keyLower = string.lower(child.Name)\n                            local relevant =\n                                string.find(keyLower, \"reforge\", 1, true)\n                                or string.find(keyLower, \"quality\", 1, true)\n\n                            if relevant then\n                                local value = child.Value\n\n                                if not quality then\n                                    quality = canonicalQuality(value)\n                                end\n\n                                if percent == nil then\n                                    percent = normalizePercent(value)\n                                        or parsePercent(value)\n                                end\n                            end\n                        end\n                    end\n                end\n\n                if not quality and percent ~= nil then\n                    quality = inferQuality(percent)\n                end\n\n                if allowUI ~= false then\n                    local uiQuality, uiPercent = M.ReadUIState()\n\n                    if uiQuality and uiPercent ~= nil then\n                        quality = uiQuality\n                        percent = uiPercent\n                    end\n                end\n\n                return quality, percent\n            end\n\n            local function resolveResultLabel(force)\n                local playerGui = ctx.LocalPlayer\n                    and ctx.LocalPlayer:FindFirstChildOfClass(\"PlayerGui\")\n                local main = playerGui and playerGui:FindFirstChild(\"Main\")\n                local root = main and main:FindFirstChild(\"Reforge\", true)\n\n                if not root then\n                    cachedResultLabel = nil\n                    cachedReforgeRoot = nil\n                    return nil\n                end\n\n                if not force\n                    and cachedResultLabel\n                    and cachedResultLabel.Parent\n                    and cachedReforgeRoot == root then\n                    return cachedResultLabel\n                end\n\n                -- Avoid repeated full scans if no valid label exists yet.\n                if not force\n                    and cachedReforgeRoot == root\n                    and os.clock() - lastLabelScan < 0.50 then\n                    return nil\n                end\n\n                lastLabelScan = os.clock()\n                cachedReforgeRoot = root\n                cachedResultLabel = nil\n\n                local bestLabel = nil\n                local bestScore = -math.huge\n                local scanned = 0\n\n                for _, gui in ipairs(root:GetDescendants()) do\n                    if gui:IsA(\"TextLabel\") or gui:IsA(\"TextButton\") then\n                        scanned = scanned + 1\n                        if scanned > 500 then\n                            break\n                        end\n\n                        local visible = true\n                        pcall(function()\n                            visible = gui.Visible\n                        end)\n\n                        if visible then\n                            local txt = tostring(gui.Text or \"\")\n                            local quality = canonicalQuality(txt)\n                            local percent = parsePercent(txt)\n\n                            if quality and percent ~= nil then\n                                local percentCount = 0\n                                for _ in string.gmatch(txt, \"%%\") do\n                                    percentCount = percentCount + 1\n                                end\n\n                                if percentCount == 1 then\n                                    local score = 0\n\n                                    if #txt <= 40 then\n                                        score = score + 10\n                                    end\n\n                                    pcall(function()\n                                        score = score\n                                            + math.min(\n                                                tonumber(gui.TextSize) or 0,\n                                                40\n                                            ) * 0.25\n                                    end)\n\n                                    pcall(function()\n                                        local absY = gui.AbsolutePosition.Y\n                                        local rootY = root.AbsolutePosition.Y\n\n                                        if absY <= rootY\n                                            + math.max(\n                                                root.AbsoluteSize.Y * 0.45,\n                                                160\n                                            ) then\n                                            score = score + 4\n                                        end\n                                    end)\n\n                                    if score > bestScore then\n                                        bestScore = score\n                                        bestLabel = gui\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n\n                cachedResultLabel = bestLabel\n                return bestLabel\n            end\n\n            function M.ReadUIState()\n                local label = resolveResultLabel(false)\n\n                if label and label.Parent then\n                    local txt = tostring(label.Text or \"\")\n                    local quality = canonicalQuality(txt)\n                    local percent = parsePercent(txt)\n\n                    if quality and percent ~= nil then\n                        return quality, percent\n                    end\n                end\n\n                return nil, nil\n            end\n\n            local function identityHint(item)\n                if not item then\n                    return nil\n                end\n\n                local attrs = item:GetAttributes()\n                local keys = {\n                    \"UUID\", \"Uid\", \"UID\",\n                    \"UniqueId\", \"UniqueID\",\n                    \"ItemId\", \"ItemID\",\n                    \"InventoryId\", \"InventoryID\",\n                }\n\n                for _, key in ipairs(keys) do\n                    local value = attrs[key]\n\n                    if value ~= nil then\n                        local s = tostring(value)\n\n                        if s ~= \"\" then\n                            if #s > 8 then\n                                s = string.sub(s, -8)\n                            end\n\n                            return s\n                        end\n                    end\n                end\n\n                return nil\n            end\n\n            function M.BuildOptions()\n                local inv = getInventory()\n                local values = {}\n                local counts = {}\n                local ordinals = {}\n\n                optionMap = {}\n                optionMeta = {}\n\n                if not inv then\n                    return { \"Select Item\" }\n                end\n\n                local children = inv:GetChildren()\n\n                for _, item in ipairs(children) do\n                    counts[item.Name] = (counts[item.Name] or 0) + 1\n                end\n\n                for index, item in ipairs(children) do\n                    local baseName = tostring(item.Name)\n                    ordinals[baseName] = (ordinals[baseName] or 0) + 1\n\n                    local ordinal = ordinals[baseName]\n                    local quality, percent = readItemState(item, false)\n\n                    local buffText = quality or \"Unknown\"\n                    if percent ~= nil then\n                        buffText = buffText\n                            .. string.format(\" %+.2f%%\", percent)\n                    end\n\n                    local suffix = \"\"\n                    if (counts[baseName] or 0) > 1 then\n                        suffix = \" #\" .. tostring(ordinal)\n                    end\n\n                    local hint = identityHint(item)\n                    if hint then\n                        suffix = suffix .. \" [\" .. hint .. \"]\"\n                    end\n\n                    local label = baseName\n                        .. \" | \"\n                        .. buffText\n                        .. suffix\n\n                    if optionMap[label] then\n                        label = label .. \" @\" .. tostring(index)\n                    end\n\n                    optionMap[label] = item\n                    optionMeta[label] = {\n                        Name = baseName,\n                        Ordinal = ordinal,\n                    }\n\n                    table.insert(values, label)\n                end\n\n                table.sort(values)\n\n                if #values == 0 then\n                    table.insert(values, \"Select Item\")\n                end\n\n                return values\n            end\n\n            local function findItem(selection)\n                local value = tostring(selection or \"\")\n\n                if value == \"\" or value == \"Select Item\" then\n                    return nil\n                end\n\n                local mapped = optionMap[value]\n                if mapped and mapped.Parent then\n                    return mapped\n                end\n\n                -- Rebuild once if Inventory changed.\n                M.BuildOptions()\n\n                mapped = optionMap[value]\n                if mapped and mapped.Parent then\n                    return mapped\n                end\n\n                local inv = getInventory()\n                local fallbackName =\n                    tostring(ctx.Config.ReforgeItemName or \"\")\n\n                if inv and fallbackName ~= \"\" then\n                    for _, item in ipairs(inv:GetChildren()) do\n                        if item.Name == fallbackName then\n                            return item\n                        end\n                    end\n                end\n\n                return nil\n            end\n\n            local function selectedItem()\n                local selector =\n                    tostring(ctx.Config.ReforgeItemSelector or \"\")\n\n                if selector == \"\" then\n                    selector = tostring(\n                        ctx.Config.ReforgeItemName or \"\"\n                    )\n                end\n\n                return findItem(selector)\n            end\n\n            local function goalState(item)\n                local quality, percent = M.ReadUIState()\n\n                if not quality or percent == nil then\n                    quality, percent = readItemState(item, false)\n                end\n\n                percent = normalizePercent(percent)\n\n                if not quality or percent == nil then\n                    return false, quality, percent\n                end\n\n                local currentRank = qualityRank[quality] or 0\n                local targetRank =\n                    qualityRank[ctx.Config.ReforgeTargetQuality] or 0\n                local minPercent =\n                    tonumber(ctx.Config.ReforgeMinPercent) or 0\n\n                return currentRank >= targetRank\n                    and percent >= minPercent,\n                    quality,\n                    percent\n            end\n\n            local function statusText()\n                local item = selectedItem()\n                local selectedName =\n                    item and item.Name\n                    or tostring(ctx.Config.ReforgeItemName or \"\")\n\n                if not item\n                    and (selectedName == \"\"\n                        or selectedName == \"Select Item\") then\n\n                    return \"Item: Not selected\"\n                        .. \"\\nCurrent: --\"\n                        .. \"\\nTarget: \"\n                        .. tostring(\n                            ctx.Config.ReforgeTargetQuality\n                                or \"Divine\"\n                        )\n                        .. \" / \"\n                        .. string.format(\n                            \"%+.2f%%\",\n                            tonumber(\n                                ctx.Config.ReforgeMinPercent\n                            ) or 0\n                        )\n                        .. \"\\nStatus: Waiting for item\"\n                end\n\n                if not item then\n                    return \"Item: \" .. selectedName\n                        .. \"\\nCurrent: Item not found\"\n                        .. \"\\nTarget: \"\n                        .. tostring(\n                            ctx.Config.ReforgeTargetQuality\n                                or \"Divine\"\n                        )\n                        .. \" / \"\n                        .. string.format(\n                            \"%+.2f%%\",\n                            tonumber(\n                                ctx.Config.ReforgeMinPercent\n                            ) or 0\n                        )\n                        .. \"\\nStatus: Waiting for item\"\n                end\n\n                local goalMet, quality, percent =\n                    goalState(item)\n\n                local currentText = quality or \"Unknown\"\n\n                if percent ~= nil then\n                    currentText = currentText\n                        .. string.format(\n                            \" (%+.2f%%)\",\n                            percent\n                        )\n                else\n                    currentText = currentText\n                        .. \" (waiting for valid Reforge data)\"\n                end\n\n                local targetText =\n                    tostring(\n                        ctx.Config.ReforgeTargetQuality\n                            or \"Divine\"\n                    )\n                    .. \" / \"\n                    .. string.format(\n                        \"%+.2f%%\",\n                        tonumber(ctx.Config.ReforgeMinPercent) or 0\n                    )\n\n                local status\n\n                if goalMet then\n                    status = \"Goal Reached \u{2713}\"\n                elseif ctx.Config.AutoReforge and busy then\n                    status = \"Reforging...\"\n                elseif ctx.Config.AutoReforge then\n                    status = \"Starting...\"\n                else\n                    status = \"Ready\"\n                end\n\n                return \"Item: \" .. selectedName\n                    .. \"\\nCurrent: \" .. currentText\n                    .. \"\\nTarget: \" .. targetText\n                    .. \"\\nAttempts: \"\n                    .. tostring(attempts)\n                    .. \" / \"\n                    .. tostring(\n                        ctx.Config.ReforgeMaxAttempts or 100\n                    )\n                    .. \"\\nStatus: \" .. status\n            end\n\n            function M.UpdateStatus()\n                if not ctx.Paragraph\n                    or type(ctx.Paragraph.SetContent)\n                        ~= \"function\" then\n                    return\n                end\n\n                local ok, content = pcall(statusText)\n\n                if not ok or type(content) ~= \"string\" then\n                    return\n                end\n\n                if content == lastStatusText then\n                    return\n                end\n\n                lastStatusText = content\n\n                pcall(function()\n                    ctx.Paragraph:SetContent(content)\n                end)\n            end\n\n            function M.SetDropdown(obj)\n                dropdown = obj\n            end\n\n            function M.Select(selected)\n                local value =\n                    type(selected) == \"table\"\n                    and (selected[1] or next(selected))\n                    or selected\n\n                value = tostring(value or \"\")\n\n                ctx.Config.ReforgeItemSelector = value\n\n                local item = findItem(value)\n                ctx.Config.ReforgeItemName =\n                    item and item.Name or \"\"\n\n                cachedResultLabel = nil\n                save()\n                M.UpdateStatus()\n            end\n\n            function M.SetQuality(selected)\n                local value =\n                    type(selected) == \"table\"\n                    and (selected[1] or next(selected))\n                    or selected\n\n                ctx.Config.ReforgeTargetQuality =\n                    tostring(value or \"Divine\")\n\n                save()\n                M.UpdateStatus()\n            end\n\n            function M.SetMinPercent(value)\n                ctx.Config.ReforgeMinPercent =\n                    tonumber(value) or 5\n\n                save()\n                M.UpdateStatus()\n            end\n\n            function M.SetMaxAttempts(value)\n                ctx.Config.ReforgeMaxAttempts =\n                    math.floor(tonumber(value) or 100)\n\n                save()\n                M.UpdateStatus()\n            end\n\n            function M.RefreshItems()\n                local values = M.BuildOptions()\n\n                if dropdown\n                    and type(dropdown.SetValues)\n                        == \"function\" then\n                    pcall(function()\n                        dropdown:SetValues(values)\n                    end)\n                end\n\n                M.UpdateStatus()\n\n                notify(\n                    \"Auto Reforge\",\n                    \"Reforge item list refreshed.\",\n                    3\n                )\n            end\n\n            function M.Inspect()\n                local item = selectedItem()\n\n                if not item then\n                    notify(\n                        \"Auto Reforge\",\n                        \"No item selected.\",\n                        3\n                    )\n                    return\n                end\n\n                cachedResultLabel = nil\n\n                local quality, percent =\n                    readItemState(item, true)\n\n                local textValue = quality or \"Unknown\"\n\n                if percent ~= nil then\n                    textValue = textValue\n                        .. string.format(\n                            \" (%+.2f%%)\",\n                            percent\n                        )\n                end\n\n                notify(\n                    \"Reforge State\",\n                    textValue,\n                    5\n                )\n\n                M.UpdateStatus()\n            end\n\n            local function runWorker()\n                if busy or not ctx.Config.AutoReforge then\n                    return\n                end\n\n                busy = true\n                attempts = 0\n                M.UpdateStatus()\n\n                task.spawn(function()\n                    local remotes =\n                        ctx.ReplicatedStorage\n                            :FindFirstChild(\"Remotes\")\n                    local upgradeRemote =\n                        remotes\n                        and remotes:FindFirstChild(\"Upgrade\")\n\n                    if not upgradeRemote\n                        or not upgradeRemote:IsA(\n                            \"RemoteFunction\"\n                        ) then\n\n                        ctx.Config.AutoReforge = false\n                        busy = false\n                        save()\n                        M.UpdateStatus()\n                        return\n                    end\n\n                    local maxAttempts = math.clamp(\n                        tonumber(\n                            ctx.Config.ReforgeMaxAttempts\n                        ) or 100,\n                        1,\n                        500\n                    )\n\n                    local unknownReads = 0\n\n                    while ctx.Config.AutoReforge\n                        and attempts < maxAttempts do\n\n                        local item = selectedItem()\n\n                        if not item or not item.Parent then\n                            break\n                        end\n\n                        local goalMet, quality, percent =\n                            goalState(item)\n\n                        if goalMet then\n                            break\n                        end\n\n                        if quality or percent ~= nil then\n                            unknownReads = 0\n                        end\n\n                        attempts = attempts + 1\n                        M.UpdateStatus()\n\n                        local ok = pcall(function()\n                            upgradeRemote:InvokeServer(\n                                \"Reforge\",\n                                item\n                            )\n                        end)\n\n                        if not ok then\n                            task.wait(0.75)\n                            break\n                        end\n\n                        -- Let the game's result label update.\n                        task.wait(0.48)\n\n                        M.UpdateStatus()\n\n                        local _, afterQuality, afterPercent =\n                            goalState(item)\n\n                        if not afterQuality\n                            or afterPercent == nil then\n\n                            unknownReads = unknownReads + 1\n\n                            if unknownReads >= 3 then\n                                break\n                            end\n                        else\n                            unknownReads = 0\n                        end\n\n                        task.wait(0.10)\n                    end\n\n                    ctx.Config.AutoReforge = false\n                    busy = false\n                    save()\n                    M.UpdateStatus()\n                end)\n            end\n\n            function M.Toggle(value)\n                ctx.Config.AutoReforge =\n                    value == true\n\n                save()\n                M.UpdateStatus()\n\n                if not value then\n                    return\n                end\n\n                local item = selectedItem()\n\n                if not item then\n                    ctx.Config.AutoReforge = false\n                    save()\n\n                    notify(\n                        \"Auto Reforge\",\n                        \"Select an inventory item first.\",\n                        4\n                    )\n\n                    M.UpdateStatus()\n                    return\n                end\n\n                runWorker()\n            end\n\n            function M.StartSaved()\n                if ctx.Config.AutoReforge then\n                    task.defer(function()\n                        task.wait(1.5)\n                        runWorker()\n                    end)\n                end\n            end\n\n            function M.StartStatusLoop()\n                task.spawn(function()\n                    while true do\n                        task.wait(\n                            ctx.Config.AutoReforge\n                            and 0.35\n                            or 1.00\n                        )\n                        M.UpdateStatus()\n                    end\n                end)\n            end\n\n            M.Qualities = qualities\n\n            return M\n        end\n    ",
